class TestVectorOperations:
    """Embedding similarity and search."""

    def test_cosine_similarity_identical(self):
        v = [1.0, 2.0, 3.0]
        assert GlobalMemoryStore.cosine_similarity(v, v) == pytest.approx(1.0)

    def test_cosine_similarity_orthogonal(self):
        a = [1.0, 0.0]
        b = [0.0, 1.0]
        assert GlobalMemoryStore.cosine_similarity(a, b) == pytest.approx(0.0)

    def test_cosine_similarity_opposite(self):
        a = [1.0, 0.0]
        b = [-1.0, 0.0]
        assert GlobalMemoryStore.cosine_similarity(a, b) == pytest.approx(-1.0)

    def test_cosine_similarity_zero_vector_raises(self):
        with pytest.raises(ValueError):
            GlobalMemoryStore.cosine_similarity([0.0, 0.0], [1.0, 0.0])

    def test_cosine_similarity_dimension_mismatch_raises(self):
        with pytest.raises(ValueError):
            GlobalMemoryStore.cosine_similarity([1.0, 2.0], [1.0])

    def test_search_by_vector_returns_ranked(self, store, valid_entry_data):
        data = valid_entry_data.copy()
        data["embedding"] = [1.0, 0.0, 0.0]
        store.add_entry(**data)
        data2 = valid_entry_data.copy()
        data2["entry_id"] = "mem_002"
        data2["embedding"] = [0.9, 0.1, 0.0]
        store.add_entry(**data2)

        results = store.search_by_vector([1.0, 0.0, 0.0], top_k=2)
        assert len(results) == 2
        assert results[0].entry_id == "mem_001"  # most similar first

    def test_search_by_vector_top_k_limit(self, store, valid_entry_data):
        for i in range(5):
            data = valid_entry_data.copy()
            data["entry_id"] = f"mem_{i:03d}"
            data["embedding"] = [float(i), 0.0, 0.0]
            store.add_entry(**data)

        results = store.search_by_vector([1.0, 0.0, 0.0], top_k=3)
        assert len(results) == 3

    def test_search_by_vector_no_embeddings_returns_empty(self, store):
        assert store.search_by_vector([1.0, 0.0]) == []

    def test_search_by_vector_skips_entries_without_embedding(self, store, valid_entry_data):
        data = valid_entry_data.copy()
        data["embedding"] = None
        store.add_entry(**data)
        data2 = valid_entry_data.copy()
        data2["entry_id"] = "mem_002"
        data2["embedding"] = [1.0, 0.0]
        store.add_entry(**data2)

        results = store.search_by_vector([1.0, 0.0], top_k=5)
        assert len(results) == 1
        assert results[0].entry_id == "mem_002"


