class TestPersistence:
    """Disk-backed storage behavior."""

    def test_store_creates_directory(self, isolated_memory_dir):
        GlobalMemoryStore()
        assert isolated_memory_dir.exists()

    def test_store_persists_to_disk(self, store, valid_entry_data):
        store.add_entry(**valid_entry_data)
        files = list(isolated_memory_dir.glob("*.json"))
        assert len(files) >= 1

    def test_store_reloads_from_disk(self, store, valid_entry_data):
        store.add_entry(**valid_entry_data)
        # Re-instantiate store to simulate restart
        store2 = GlobalMemoryStore()
        entry = store2.get_entry("mem_001")
        assert entry is not None
        assert entry.content == "Vector store operational"

    def test_serialization_roundtrip(self, store, valid_entry_data):
        store.add_entry(**valid_entry_data)
        store2 = GlobalMemoryStore()
        entry = store2.get_entry("mem_001")
        assert entry.entry_id == "mem_001"
        assert entry.memory_type == MemoryType.EPISODIC
        assert entry.embedding == pytest.approx([0.1, 0.2, 0.3])

    def test_corrupt_json_file_handled(self, isolated_memory_dir):
        (isolated_memory_dir / "corrupt.json").write_text("{not valid json")
        # Should not crash on init
        store = GlobalMemoryStore()
        assert store.count_entries() == 0


