class TestErrorPaths:
    """Defensive programming validation."""

    def test_add_entry_with_invalid_data_raises(self, store):
        with pytest.raises(ValidationError):
            store.add_entry(entry_id="x", content="", author="tester")

    def test_get_entry_with_none_id(self, store):
        with pytest.raises(ValueError):
            store.get_entry(None)

    def test_get_entry_with_empty_string(self, store):
        assert store.get_entry("") is None

    def test_update_entry_with_none_id(self, store):
        with pytest.raises(ValueError):
            store.update_entry(None, content="x")

    def test_delete_entry_with_none_id(self, store):
        with pytest.raises(ValueError):
            store.delete_entry(None)

    def test_search_by_vector_with_wrong_dimension(self, store, valid_entry_data):
        data = valid_entry_data.copy()
        data["embedding"] = [1.0, 0.0, 0.0]
        store.add_entry(**data)
        with pytest.raises(ValueError):
            store.search_by_vector([1.0, 0.0], top_k=1)

    def test_search_by_vector_with_empty_query(self, store):
        with pytest.raises(ValueError):
            store.search_by_vector([], top_k=1)

    def test_search_by_vector_with_negative_top_k(self, store):
        with pytest.raises(ValueError):
            store.search_by_vector([1.0, 0.0], top_k=-1)

    def test_search_by_vector_with_zero_top_k(self, store):
        assert store.search_by_vector([1.0, 0.0], top_k=0) == []


