        @given(st.text(min_size=1, max_size=20))
        def _check(entry_id):
            store = GlobalMemoryStore()
            data = {
                "entry_id": entry_id,
                "content": "test content",
                "author": "hypothesis",
            }
            store.add_entry(**data)
            assert store.get_entry(entry_id) is not None

        _check()


